import type { Metadata } from "next";
import { robotsDirectives } from "./seo";
import { site } from "./site";

/** Site-wide sharing image generated by app/opengraph-image.tsx. */
export const socialImage = {
  url: "/opengraph-image",
  width: 1200,
  height: 630,
  alt: `${site.name}: ${site.tagline} ${site.message}`,
} as const;

interface PageMetadataInput {
  readonly title: string;
  readonly description: string;
  /** Path relative to `metadataBase`, for example "/shop". */
  readonly path: string;
  /** Opt this page out of indexing. Cannot opt in while indexing is disabled. */
  readonly noIndex?: boolean;
}

/**
 * Builds page metadata with a canonical URL and a complete Open Graph block.
 * Next.js merges `openGraph` shallowly, so each page supplies every field,
 * including the image (otherwise the root opengraph-image is dropped).
 */
export function pageMetadata({
  title,
  description,
  path,
  noIndex = false,
}: PageMetadataInput): Metadata {
  return {
    title,
    description,
    alternates: { canonical: path },
    openGraph: {
      type: "website",
      siteName: site.name,
      locale: site.locale,
      url: path,
      title: `${title} — ${site.name}`,
      description,
      images: [socialImage],
    },
    // Always set, from the global switch, so a page can never loosen it.
    robots: robotsDirectives({ noIndex }),
  };
}
